/*
  # Security Hardening: search_path Pinning and RLS Tightening

  Critical security fixes:
  1. Pin search_path in 29 SECURITY DEFINER functions
  2. Fix sales_profit_summary VIEW to SECURITY INVOKER
  3. Close unrestricted RLS policy on customers
*/

CREATE OR REPLACE FUNCTION calculate_sale_profit(sale_id_param uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ DECLARE v_total_cost numeric; v_total_revenue numeric; v_gross_profit numeric; v_profit_margin numeric; BEGIN SELECT COALESCE(SUM(purchase_price * quantity), 0) INTO v_total_cost FROM sale_items WHERE sale_id = sale_id_param; SELECT total INTO v_total_revenue FROM sales WHERE id = sale_id_param; v_gross_profit := v_total_revenue - v_total_cost; IF v_total_revenue > 0 THEN v_profit_margin := (v_gross_profit / v_total_revenue) * 100; ELSE v_profit_margin := 0; END IF; UPDATE sales SET total_cost = v_total_cost, gross_profit = v_gross_profit, profit_margin = v_profit_margin, updated_at = now() WHERE id = sale_id_param; END; $$;

CREATE OR REPLACE FUNCTION update_sale_profit_trigger() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF TG_OP = 'DELETE' THEN PERFORM calculate_sale_profit(OLD.sale_id); ELSE PERFORM calculate_sale_profit(NEW.sale_id); END IF; RETURN NULL; END; $$;

CREATE OR REPLACE FUNCTION freeze_sales_financials() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF current_setting('app.bypass_immutable', true) = 'true' THEN RETURN NEW; END IF; IF OLD.is_deleted = true THEN RAISE EXCEPTION 'Cannot update a deleted record on sales. Record ID: %', OLD.id; END IF; IF NEW.subtotal IS DISTINCT FROM OLD.subtotal OR NEW.tax IS DISTINCT FROM OLD.tax OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.total IS DISTINCT FROM OLD.total OR NEW.delivery_charge IS DISTINCT FROM OLD.delivery_charge THEN RAISE EXCEPTION 'Financial values (subtotal, tax, discount, total, delivery_charge) on sales are frozen after creation. Use void/reversal. Record ID: %', OLD.id; END IF; RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION freeze_sale_items_financials() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF current_setting('app.bypass_immutable', true) = 'true' THEN RETURN NEW; END IF; IF OLD.is_deleted = true THEN RAISE EXCEPTION 'Cannot update a deleted record on sale_items. Record ID: %', OLD.id; END IF; IF NEW.quantity IS DISTINCT FROM OLD.quantity OR NEW.unit_price IS DISTINCT FROM OLD.unit_price OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.total IS DISTINCT FROM OLD.total OR NEW.purchase_price IS DISTINCT FROM OLD.purchase_price THEN RAISE EXCEPTION 'Financial values on sale_items are frozen after creation. Record ID: %', OLD.id; END IF; RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION freeze_purchases_financials() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF current_setting('app.bypass_immutable', true) = 'true' THEN RETURN NEW; END IF; IF OLD.is_deleted = true THEN RAISE EXCEPTION 'Cannot update a deleted record on purchases. Record ID: %', OLD.id; END IF; IF NEW.subtotal IS DISTINCT FROM OLD.subtotal OR NEW.tax IS DISTINCT FROM OLD.tax OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.total IS DISTINCT FROM OLD.total THEN RAISE EXCEPTION 'Financial values on purchases are frozen after creation. Use void/reversal. Record ID: %', OLD.id; END IF; RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION freeze_purchase_items_financials() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF current_setting('app.bypass_immutable', true) = 'true' THEN RETURN NEW; END IF; IF OLD.is_deleted = true THEN RAISE EXCEPTION 'Cannot update a deleted record on purchase_items. Record ID: %', OLD.id; END IF; IF NEW.quantity IS DISTINCT FROM OLD.quantity OR NEW.unit_price IS DISTINCT FROM OLD.unit_price OR NEW.discount IS DISTINCT FROM OLD.discount OR NEW.total IS DISTINCT FROM OLD.total THEN RAISE EXCEPTION 'Financial values on purchase_items are frozen after creation. Record ID: %', OLD.id; END IF; RETURN NEW; END; $$;

CREATE OR REPLACE FUNCTION freeze_expenses_financials() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF current_setting('app.bypass_immutable', true) = 'true' THEN RETURN NEW; END IF; IF OLD.is_deleted = true THEN RAISE EXCEPTION 'Cannot update a deleted record on expenses. Record ID: %', OLD.id; END IF; IF NEW.amount IS DISTINCT FROM OLD.amount THEN RAISE EXCEPTION 'Financial value (amount) on expenses is frozen after creation. Use void/reversal. Record ID: %', OLD.id; END IF; RETURN NEW; END; $$;

